/* Courbe des futures : F(t) = S*(1+c)^t sur 2 ans, contango vs backwardation */
(function () {
  var svg = document.getElementById("mp-chart");
  if (!svg) return;
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }
  function al(){ return document.body.getAttribute("data-active-lang")||"fr"; }

  function draw(){
    var S=v("mp-s"), c=v("mp-c")/100;
    setT("mp-s-o", S.toFixed(0)); setT("mp-c-o",(c*100).toFixed(1)+"%");
    var f1 = S*Math.pow(1+c,1);
    setT("mp-f1", f1.toFixed(1)+" $");
    setT("mp-roll", (-c*100).toFixed(1)+"%");
    var shape;
    if (c>0.001) shape = al()==="en"?"contango":(al()==="nl"?"contango":"contango");
    else if (c<-0.001) shape = al()==="en"?"backwardation":(al()==="nl"?"backwardation":"backwardation");
    else shape = al()==="en"?"flat":(al()==="nl"?"vlak":"plate");
    setT("mp-shape", shape);

    var W=520,H=260,L=46,R=14,T=16,B=32, pw=W-L-R, ph=H-T-B;
    var Tmax=2;
    // échelle y : englobe S et F sur 2 ans dans les deux sens
    var fend = S*Math.pow(1+c,Tmax);
    var ymin = Math.min(S, fend)*0.9;
    var ymax = Math.max(S, fend)*1.1;
    if (ymax-ymin<1){ ymin=S*0.9; ymax=S*1.1; }
    function px(t){ return L + t/Tmax*pw; }
    function py(y){ return T + (1-(y-ymin)/(ymax-ymin))*ph; }

    var g2="";
    g2+='<line class="axis" x1="'+L+'" y1="'+T+'" x2="'+L+'" y2="'+(T+ph)+'"/>';
    g2+='<line class="axis" x1="'+L+'" y1="'+(T+ph)+'" x2="'+(L+pw)+'" y2="'+(T+ph)+'"/>';
    // ligne spot horizontale (repère)
    g2+='<line x1="'+L+'" y1="'+py(S).toFixed(1)+'" x2="'+(L+pw)+'" y2="'+py(S).toFixed(1)+'" stroke="var(--ink-mute)" stroke-width="1" stroke-dasharray="4 3"/>';
    g2+='<text class="tick" x="'+(L+4)+'" y="'+(py(S)-4).toFixed(1)+'" text-anchor="start">spot '+S.toFixed(0)+'</text>';
    // courbe des futures
    var N=100, d="";
    for (var i=0;i<=N;i++){
      var tt = Tmax*i/N;
      var ff = S*Math.pow(1+c,tt);
      d += (d===""?"M ":" L ")+px(tt).toFixed(1)+","+py(ff).toFixed(1);
    }
    var col = c>0.001 ? "var(--crimson)" : (c<-0.001 ? "var(--teal)" : "var(--ink)");
    g2+='<path d="'+d+'" fill="none" stroke="'+col+'" stroke-width="2.6"/>';
    // point à 1 an
    g2+='<circle cx="'+px(1).toFixed(1)+'" cy="'+py(f1).toFixed(1)+'" r="4" fill="var(--ink)"/>';
    // ticks x
    g2+='<text class="tick" x="'+L+'" y="'+(H-16)+'" text-anchor="start">0</text>';
    g2+='<text class="tick" x="'+px(1).toFixed(1)+'" y="'+(H-16)+'" text-anchor="middle">1 '+(al()==="en"?"yr":(al()==="nl"?"jr":"an"))+'</text>';
    g2+='<text class="tick" x="'+(L+pw)+'" y="'+(H-16)+'" text-anchor="end">2 '+(al()==="en"?"yr":(al()==="nl"?"jr":"ans"))+'</text>';
    // ticks y
    g2+='<text class="tick" x="'+(L-6)+'" y="'+(py(ymax)+4).toFixed(1)+'" text-anchor="end">'+ymax.toFixed(0)+'</text>';
    g2+='<text class="tick" x="'+(L-6)+'" y="'+(py(ymin)+0).toFixed(1)+'" text-anchor="end">'+ymin.toFixed(0)+'</text>';
    var xlab = al()==="en"?"maturity (years)":(al()==="nl"?"looptijd (jaren)":"échéance (années)");
    var ylab = al()==="en"?"futures price":(al()==="nl"?"futuresprijs":"prix future");
    g2+='<text class="lab" x="'+(L+pw/2)+'" y="'+(H-3)+'" text-anchor="middle">'+xlab+'</text>';
    g2+='<text class="lab" x="'+(L-36)+'" y="'+(T+ph/2)+'" text-anchor="middle" transform="rotate(-90 '+(L-36)+' '+(T+ph/2)+')">'+ylab+'</text>';
    svg.innerHTML=g2;
  }

  ["mp-s","mp-c"].forEach(function(id){ var e=document.getElementById(id); if(e) e.addEventListener("input", draw); });
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
